input.command:
ssh scriptkid@13.140.155.113 -i ~/.ssh/idiot-doll 'cd ~/opt/cloud/dev/butlerAi && find . -type f -not -path "./.git/*" -exec sha1sum {} + 2>/dev/null' > /tmp/cloud-sums.txt; find . -type f -not -path "./.git/*" -not -path "./android/app/build/*" -not -path "./android/.gradle/*" -not -path "./.opencode/node_modules/*" -exec sha1sum {} + 2>/dev/null > /tmp/local-sums.txt; python3 -c "
import collections
def load(p):
    d={}
    for line in open(p):
        h,_,f=line.strip().partition('  '); f=f or _; 
        parts=line.strip().split(None,1)
        if len(parts)==2: d[parts[1]]=parts[0]
    return d
c=load('/tmp/cloud-sums.txt'); l=load('/tmp/local-sums.txt')
print('cloud files:',len(c),'local files (excl build/gradle/nodemodules):',len(l))
print('=== cloud-only ===')
for f in sorted(set(c)-set(l)): print(' ',f)
print('=== local-only (non-noise) ===')
loc=sorted(set(l)-set(c))
for f in loc[:80]: print(' ',f)
print('  ... total local-only:',len(loc))
print('=== shared but DIFFERENT content ===')
diff=[f for f in set(c)&set(l) if c[f]!=l[f]]
for f in sorted(diff)[:60): print(' ',f)
print('  ... total differing:',len(diff))
print('=== shared identical:', sum(1 for f in set(c)&set(l) if c[f]==l[f]))
"

